{
  "name": "rich-opencode",
  "version": "1.2.2",
  "description": "Discord Rich Presence plugin for OpenCode. Shows your model, context usage, activity status, and play-session timer.",
  "type": "module",
  "license": "MIT",
  "author": "YonCZ",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "discord",
    "discord-rpc",
    "rich-presence",
    "presence",
    "plugin"
  ],
  "homepage": "https://github.com/YonCZ/OpenCode-Presence",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/YonCZ/OpenCode-Presence.git"
  },
  "bugs": {
    "url": "https://github.com/YonCZ/OpenCode-Presence/issues"
  },
  "engines": {
    "node": ">=20"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "oc-plugin": [
    "server",
    "tui"
  ],
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "AGENT_INSTALL.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "prepack": "npm run build",
    "preview": "node preview.mjs",
    "diagnose": "node diagnose.mjs",
    "prepare": "npm run build"
  },
  "dependencies": {
    "@xhayper/discord-rpc": "^1.3.4"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.32",
    "@opencode/plugin": "^2.0.14",
    "@types/node": "^25.8.0",
    "typescript": "^5.8.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.29",
    "@opencode/plugin": ">=2.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    }
  }
}

import type { Plugin } from "@opencode-ai/plugin";
import { createV1Hooks } from "./v1.js";
import { createV2Plugin, pluginId } from "./v2.js";

export type { RichOptions } from "./options.js";

const v2 = createV2Plugin();

/**
 * One package, two host generations:
 * OpenCode 2 calls `setup`, OpenCode 1.18.29 and newer call `server`.
 * Older V1 releases expect a function instead of an object and are not supported.
 */
const plugin = {
  id: pluginId,
  setup: v2.setup,
  server: (input: Parameters<Plugin>[0], options?: Parameters<Plugin>[1]) => createV1Hooks(input, options),
};

export default plugin;
